//! Variational loops: parameter-shift gradients and the descent.
//!
//! For a gate generated by a Pauli (eigenvalues ±1/2), the exact
//! gradient is a difference of two shifted expectations — no finite
//! differences, no step-size dilemma, because sine and cosine are
//! their own shifted differences. The managed mirror shifts the same
//! way.

use std::f32::consts::FRAC_PI_2;

/// The exact gradient of `expectation` at `theta`, by the parameter
/// shift: half the difference between the expectations at θ+π/2 and
/// θ−π/2.
///
/// The shift is exact for Pauli rotations: d/dθ cos θ is
/// (cos(θ+π/2) − cos(θ−π/2))/2, bit for bit up to the evaluation of
/// the two expectations.
pub fn parameter_shift_gradient(expectation: &dyn Fn(f32) -> f32, theta: f32) -> f32 {
    0.5 * (expectation(theta + FRAC_PI_2) - expectation(theta - FRAC_PI_2))
}

/// Gradient descent with a fixed step count and rate: deterministic
/// to the bit. Returns the final parameters beside the final energy.
pub fn descend(
    initial: &[f32],
    steps: usize,
    rate: f32,
    energy: &dyn Fn(&[f32]) -> f32,
    gradient: &dyn Fn(&[f32]) -> Vec<f32>,
) -> (Vec<f32>, f32) {
    let mut params = initial.to_vec();
    for _ in 0..steps {
        let g = gradient(&params);
        for (p, gi) in params.iter_mut().zip(g.iter()) {
            *p -= rate * gi;
        }
    }
    let final_energy = energy(&params);
    (params, final_energy)
}
